class FeistelScrambler(
    private val key: Long,
    private val domainSize: Int,
    private val rounds: Int = 8
) {
    private val rightModulus: Int
    private val leftModulus: Int

    init {
        val sqrt = ceil(sqrt(domainSize.toDouble())).toInt()
        rightModulus = sqrt
        leftModulus = sqrt
        require(leftModulus.toLong() * rightModulus >= domainSize) {
            "Domain split failed: $leftModulus * $rightModulus < $domainSize"
        }
    }

    private fun roundFunction(value: Int, round: Int, modulus: Int): Int {
        var h = value.toLong()
        h = h * 2654435761L + key
        h = h * 2246822519L + round.toLong()
        h = h xor (h ushr 16)
        h = h * 2654435761L
        h = h xor (h ushr 13)
        h = h * 3266489917L
        h = h xor (h ushr 16)
        return h.mod(modulus.toLong()).toInt()
    }

    fun scramble(input: Int): Int {
        require(input in 0 until domainSize) { "Input $input outside domain [0, $domainSize)" }
        var value = input
        do {
            var left = value / rightModulus
            var right = value % rightModulus
            for (round in 0 until rounds) {
                val newLeft = right
                val newRight = (left + roundFunction(right, round, leftModulus)) % leftModulus
                left = newLeft
                right = newRight
            }
            value = left * rightModulus + right
        } while (value >= domainSize)
        return value
    }

    fun unscramble(input: Int): Int {
        require(input in 0 until domainSize) { "Input $input outside domain [0, $domainSize)" }
        var value = input
        do {
            var left = value / rightModulus
            var right = value % rightModulus
            for (round in (rounds - 1) downTo 0) {
                val newRight = left
                val newLeft = (right.toLong() - roundFunction(left, round, leftModulus).toLong())
                    .mod(leftModulus.toLong()).toInt()
                left = newLeft
                right = newRight
            }
            value = left * rightModulus + right
        } while (value >= domainSize)
        return value
    }
}

