import kotlin.math.ceil
import kotlin.math.sqrt

class FeistelScrambler(
    private val key: Long,
    private val domainSize: Int,
) {
    private val rounds = 8
    private val halfModulus = ceil(sqrt(domainSize.toDouble())).toInt()

    init {
        require(halfModulus.toLong() * halfModulus >= domainSize) {
            "Domain split failed: $halfModulus * $halfModulus < $domainSize"
        }
    }

    private fun roundFunction(value: Int, round: Int): Int {
        var h = value.toLong()
        h = h * 2654435761L + key
        h = h * 2246822519L + round.toLong()
        h = h xor (h ushr 16)
        h = h * 2654435761L
        h = h xor (h ushr 13)
        h = h * 3266489917L
        h = h xor (h ushr 16)
        return h.mod(halfModulus.toLong()).toInt()
    }

    fun scramble(input: Int): Int {
        require(input in 0 until domainSize) { "Input $input outside domain [0, $domainSize)" }
        var value = input
        do {
            var left = value / halfModulus
            var right = value % halfModulus
            for (round in 0 until rounds) {
                val newLeft = right
                val newRight = (left + roundFunction(right, round)) % halfModulus
                left = newLeft
                right = newRight
            }
            value = left * halfModulus + right
        } while (value >= domainSize)
        return value
    }

    fun unscramble(input: Int): Int {
        require(input in 0 until domainSize) { "Input $input outside domain [0, $domainSize)" }
        var value = input
        do {
            var left = value / halfModulus
            var right = value % halfModulus
            for (round in (rounds - 1) downTo 0) {
                val newRight = left
                val newLeft = (right.toLong() - roundFunction(left, round).toLong())
                    .mod(halfModulus.toLong()).toInt()
                left = newLeft
                right = newRight
            }
            value = left * halfModulus + right
        } while (value >= domainSize)
        return value
    }
}

